import { Router } from 'express';
import { z } from 'zod';
import type { ConfigManager } from '../services/ConfigManager';
import type {
  ErrorResponse,
  SignInBrowserLaunchResponse,
} from '../types/api-responses';
import { parseLaunchableUrl } from '../utils/launchableUrl';
import { createLogger } from '../utils/logger';
import { isLocalBrowserRequest } from './library/middleware';

const log = createLogger('SignInLaunchRoutes');
const SIGN_IN_UNAVAILABLE = 'Could not start Google sign-in.';

const GoogleSignInStartResponseSchema = z.object({
  success: z.boolean(),
  authUrl: z.string().optional(),
  sessionId: z.string().optional(),
  pollSecret: z.string().optional(),
  error: z.string().optional(),
  message: z.string().optional(),
});

type SignInConfig = Pick<ConfigManager, 'getProxyUrl' | 'getInstallRef'>;

type GoogleSignInStart =
  | { isStarted: true; authUrl: string; sessionId: string; pollSecret: string }
  | { isStarted: false; error: string };

const startGoogleSignIn = async (
  config: SignInConfig,
): Promise<GoogleSignInStart> => {
  const installRef = config.getInstallRef();
  const response = await fetch(
    `${config.getProxyUrl()}/api/auth/google/start`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        source: 'core',
        ...(installRef ? { ref: installRef } : {}),
      }),
    },
  );
  const parsed = GoogleSignInStartResponseSchema.safeParse(
    await response.json().catch(() => null),
  );
  if (!parsed.success) return { isStarted: false, error: SIGN_IN_UNAVAILABLE };
  const { success, authUrl, sessionId, pollSecret, error, message } =
    parsed.data;
  if (!response.ok || !success || !authUrl || !sessionId || !pollSecret) {
    return { isStarted: false, error: error || message || SIGN_IN_UNAVAILABLE };
  }
  return { isStarted: true, authUrl, sessionId, pollSecret };
};

export const createSignInLaunchRouter = ({
  openExternalUrl,
  config,
}: {
  openExternalUrl: (url: string) => Promise<unknown>;
  config: SignInConfig;
}) => {
  const router = Router();

  router.post('/auth/browser-launches', async (req, res) => {
    if (!isLocalBrowserRequest(req)) return res.sendStatus(403);
    let start: GoogleSignInStart;
    try {
      start = await startGoogleSignIn(config);
    } catch {
      log.warn('Could not reach the sign-in service');
      return res
        .status(502)
        .json({ error: SIGN_IN_UNAVAILABLE } satisfies ErrorResponse);
    }
    if (!start.isStarted) {
      log.warn('Google sign-in did not start:', start.error);
      return res
        .status(502)
        .json({ error: start.error } satisfies ErrorResponse);
    }
    const authUrl = parseLaunchableUrl(start.authUrl);
    if (!authUrl) {
      log.warn('Rejected an unsafe Google sign-in page');
      return res
        .status(502)
        .json({ error: SIGN_IN_UNAVAILABLE } satisfies ErrorResponse);
    }
    let isLaunched = true;
    try {
      await openExternalUrl(authUrl);
    } catch {
      log.warn('Could not open the Google sign-in page');
      isLaunched = false;
    }
    return res.json({
      authUrl,
      sessionId: start.sessionId,
      pollSecret: start.pollSecret,
      isLaunched,
    } satisfies SignInBrowserLaunchResponse);
  });

  return router;
};
